			if (itemNo == 0)
			{
				onComplete?.Invoke();
				return;
			}

			MessageWordSetHelper.SetPokemonNickNameWord(0, pokemonParam, true);
			MessageWordSetHelper.SetItemWord(1, itemNo, 1);
			msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Zukan, "SS_pokedex_066", true, false, () =>
			{
				var param = new ContextMenuWindow.Param
				{
					itemParams = new ContextMenuItem.Param[]
					{
						new ContextMenuItem.Param { menuId = ContextMenuID.ZUKANREGISTER_ITEM_RETURN_TO_BAG },
						new ContextMenuItem.Param { menuId = ContextMenuID.ZUKANREGISTER_ITEM_SEND_TO_BOX },
					},
					pivot = contextMenuPositionRectTransform.pivot,
					position = contextMenuPositionRectTransform.position,
				};
				ContextMenuWindow contextMenu = UIManager.Instance.CreateUIWindow<ContextMenuWindow>(UIWindowID.CONTEXTMENU);
				contextMenu.onClosed = _ => { };
				contextMenu.onClicked = item =>
				{
					if (item.param.menuId == ContextMenuID.ZUKANREGISTER_ITEM_RETURN_TO_BAG)
					{
						if (ItemWork.IsAddItem(itemNo, 1))
						{
							ItemWork.AddItem(itemNo, 1);
							pokemonParam.RemoveItem();
							ushort formNo = pokemonParam.GetFormNo();
							ushort nextFormNo = pokemonParam.GetNextFormNoFromHoldItem(pokemonParam.GetItem());
							if (formNo != nextFormNo)
							{
								pokemonParam.ChangeFormNo(nextFormNo, null);
								ZukanWork.SetPoke(pokemonParam, GET_STATUS.GET);
							}
							MessageWordSetHelper.SetItemWord(0, itemNo, 1);
							msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Zukan, "SS_pokedex_071", true, false, null, onComplete);
						}
						else
						{
							msgWindowController.OpenMsgWindow(UIMsgWindowController.MessageFileType.Zukan, "SS_pokedex_072", true, false, null, onComplete);
						}
					}
					else
					{
						msgWindowController.CloseMsgWindow();
						onComplete?.Invoke();
					}
					return true;
				};
				contextMenu.Open(param);
			}, null);
		}
